/* Built-in profiles (port of crates/cms/src/builtin.rs). All are generated from published
 * colorimetric definitions and dedicated to the public domain (CC0-1.0).
 *
 * Profiles are built once per process (thread-safe) and shared read-only; never free them. */
#ifndef PC_CMS_BUILTIN_H
#define PC_CMS_BUILTIN_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#include "profile.h"

#define PC_BUILTIN_COPYRIGHT "No copyright: CC0-1.0 public domain dedication. Generated by photocraft-cms."

/* Declaration order matches the reference. */
typedef enum pc_builtin {
    PC_BUILTIN_SRGB,             /* sRGB IEC 61966-2.1 */
    PC_BUILTIN_DISPLAY_P3,       /* DCI-P3 primaries, D65, sRGB curve */
    PC_BUILTIN_ADOBE_RGB_COMPAT, /* Adobe RGB (1998) primaries, D65, gamma 563/256 */
    PC_BUILTIN_PROPHOTO_COMPAT,  /* ROMM primaries, D50, gamma 1.8 */
    PC_BUILTIN_LINEAR_SRGB,      /* sRGB primaries, linear */
    PC_BUILTIN_REC2020,          /* Rec. 2020 primaries, Rec. 709 OETF */
    PC_BUILTIN_GRAY_GAMMA22,     /* gray, gamma 2.2 */
    PC_BUILTIN_SGRAY,            /* gray with the sRGB curve */
    PC_BUILTIN_LAB_D50,          /* Lab identity (v4 encoding) */
    PC_BUILTIN_COATED_CMYK,      /* synthetic coated offset CMYK (300% TAC, medium GCR) */
    PC_BUILTIN_COUNT
} pc_builtin;

const char *pc_builtin_id(pc_builtin b);          /* "srgb", "display-p3", ... */
const char *pc_builtin_description(pc_builtin b); /* the desc tag */
/* Id lookup: ASCII case-insensitive with non-alphanumerics ignored, a few aliases, or a
 * description (ASCII case-insensitive). */
bool pc_builtin_from_id(const char *s, size_t len, pc_builtin *out);

/* The profile, or NULL if it could not be built (out of memory). */
const pc_profile *pc_builtin_profile(pc_builtin b);
/* sRGB, sGray, coated CMYK or Lab D50 for those spaces; NULL otherwise. */
const pc_profile *pc_builtin_default_for(uint32_t space);

/* Gray with a linear tone curve ("Linear Gray (Photocraft)"): what a grayscale OpenEXR holds. Not
 * a pc_builtin, as it is only assigned to such files, never offered as a working space. NULL if
 * it could not be built (out of memory). */
const pc_profile *pc_builtin_linear_gray(void);

/* The shipped synthetic CMYK profile (data/profiles/photocraft-coated-cmyk.icc, embedded). */
extern const unsigned char pc_coated_cmyk_icc[];
extern const size_t pc_coated_cmyk_icc_len;

#endif
